const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dcGeometry = ee.Geometry.Point([-77.0369, 38.9072]).buffer(10000); // Washington D.C. center with 10km buffer
  const startDate = '2018-01-01';
  const endDate = '2019-01-01';

  // 2. Data Acquisition - Try CHIRPS daily precipitation first
  let precipCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(dcGeometry);

  let colSize = precipCol.size().getInfo();
  console.log(`CHIRPS Daily Images: ${colSize}`);

  // 3. Check for empty collection
  if (colSize === 0) {
    // Try monthly CHIRPS as fallback
    precipCol = ee.ImageCollection('UCSB-CHG/CHIRPS/MONTHLY')
      .filterDate(startDate, endDate)
      .filterBounds(dcGeometry);
    colSize = precipCol.size().getInfo();
    console.log(`CHIRPS Monthly Images: ${colSize}`);

    if (colSize === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 4. Calculate total precipitation for the year
  const totalPrecip = precipCol.sum();

  // 5. Check valid pixels
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dcGeometry,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid Pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 6. Calculate mean precipitation and convert to inches
  const meanPrecip = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dcGeometry,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // Convert mm to inches (1 inch = 25.4 mm)
  const precipInches = meanPrecip / 25.4;

  console.log(`Annual Precipitation: ${precipInches.toFixed(2)} inches`);

  // 7. Validation & Final Answer
  if (precipInches === null || precipInches === undefined || isNaN(precipInches)) {
    console.log("<answer>C3</answer>");
  } else if (precipInches < 0 || precipInches > 200) { // Unreasonable range check
    console.log("<answer>C3</answer>");
  } else if (precipInches >= 50) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
